const catalog = (area) => {
  const title = areas[area - 1][1];
  const rows = topics[area - 1].map((topic, i) => area + '.' + (i + 1) + ' ' + topic);
  return '**' + title + '**\n\n' + rows.join('  \n') + '\n\nRespondé con el código o contame tu consulta.\n0 · Menú principal';
};

const mainMenu = '**Portal del Litigante · Justicia de la Ciudad**\n\n' +
  areas.map(([, name], i) => (i + 1) + '. ' + name).join('\n') +
  '\n\nRespondé con un número o escribí tu consulta. Para atención humana, escribí **contacto**.';

const areasByCode = ['REG', 'FD', 'ESC', 'CED', 'CON', 'SOP'];
function cardId(code) {
  const [area, item] = code.split('.').map(Number);
  const number = area === 3 ? [3, 1, 2, 4, 5][item - 1] : item;
  return 'VEC-PL-' + areasByCode[area - 1] + '-0' + number;
}
const trainingPhrases = {"1.1": ["Quiero darme de alta", "Todavía no tengo usuario", "¿Cómo me inscribo en el portal?"], "1.2": ["Necesito sumar otra matrícula", "Quiero agregar otro perfil profesional", "¿Cómo incorporo mi rol de mandatario?"], "1.3": ["¿Dónde me verifican la identidad?", "¿Tengo que ir para que me identifiquen?", "Me pidieron validar quién soy"], "1.4": ["Sigo esperando que me activen", "Nunca me llegó la confirmación del registro", "¿Cómo sé si aprobaron mi alta?"], "1.5": ["Necesito que me habiliten ya", "No puedo esperar el alta", "Me urge activar la cuenta"], "1.6": ["No me acuerdo de la clave", "¿Cómo vuelvo a entrar si perdí la contraseña?", "Me olvidé el password"], "2.1": ["¿Cómo saco el certificado para firmar a distancia?", "Quiero habilitar la firma desde el celular", "Necesito enrolarme para firmar sin token"], "2.2": ["¿Cómo firmo un escrito desde el firmador remoto?", "Quiero aplicar mi firma remota a la presentación", "¿Cómo uso la firma del celular en la cédula?"], "2.3": ["La computadora no me toma el dispositivo de firma", "¿Qué controlador necesita mi token?", "No me aparece el token conectado"], "2.4": ["¿Cómo pongo mi firma usando el token?", "Se me trabó el PIN del dispositivo de firma", "Necesito firmar con el dispositivo USB"], "2.5": ["Tenemos que firmar dos personas en el mismo archivo", "¿Cómo le agrego una segunda firma?", "El PDF lleva la firma de dos abogados"], "2.6": ["¿Cómo compruebo si la firma del archivo es válida?", "Adobe dice que la firma es desconocida", "Quiero revisar el certificado de un PDF firmado"], "3.1": ["Necesito empezar un juicio nuevo", "¿Cómo doy de alta un expediente nuevo?", "¿Dónde cargo la demanda para iniciar?"], "3.2": ["¿Cómo subo una presentación con anexos?", "Tengo que adjuntar documentación a mi escrito", "Quiero cargar un escrito en un expediente que ya existe"], "3.3": ["Es la primera vez que me presento en el expediente", "¿Dónde constituyo domicilio digital?", "Quiero presentarme y denunciar el domicilio electrónico"], "3.4": ["¿Dónde pongo el comprobante del bono?", "Tengo que cargar el bono de abogados", "¿En qué pantalla integro el derecho fijo?"], "3.5": ["Necesito que este escrito quede reservado", "Quiero presentar un archivo con acceso restringido", "¿Cómo cargo documentación bajo reserva?"], "4.1": ["¿Cómo mando una cédula en papel?", "Necesito notificar en una dirección física", "La cédula va a un domicilio real"], "4.2": ["Quiero practicar una notificación por vía digital", "¿Dónde genero una cédula para el domicilio electrónico?", "¿Cómo preparo la cédula electrónica?"], "4.3": ["La cédula me volvió con observaciones", "Me devolvieron la notificación para corregir", "¿Dónde veo por qué observaron la cédula?"], "4.4": ["Necesito asentar una nota en la causa", "¿Dónde puedo dejar una nota de secretaría?", "Quiero registrar una nota en el expediente"], "5.1": ["¿Dónde busco un expediente por número?", "Quiero encontrar una causa por el nombre de las partes", "Tengo el CUIJ y quiero buscar el expediente"], "5.2": ["¿Dónde veo cuándo hay audiencias?", "Quiero consultar el calendario del juzgado", "¿Cómo entro a la agenda de audiencias?"], "5.3": ["¿Dónde consulto qué zona corresponde a una dirección?", "Quiero ubicar la zona para diligenciar la cédula", "¿Hay un mapa de zonas para notificar?"], "6.1": ["El navegador me bloquea una ventanita", "El visor no se abre", "¿Cómo habilito los popups del portal?"], "6.2": ["Me rebota el PDF", "El archivo excede el peso que me pide la pantalla", "No puedo cargar el PDF adjunto"], "6.3": ["¿Cómo me comunico con Defensa del Litigante?", "Necesito el número de la oficina del litigante", "¿A qué mail le escribo a soporte?"], "6.4": ["No me aparece el expediente", "El expediente no sale en la sección de mis causas", "La causa que tengo vinculada dejó de aparecer"]};
function chooseTopic(code) {
  if (code === '1.5') return route('habilitación urgente');
  const [area, item] = code.split('.').map(Number);
  return 'Consulta documental: [' + cardId(code) + '] ' + topics[area - 1][item - 1];
}
function route(message) {
  const input = String(message ?? '');
  if (input.length > 3000) {
    return 'Resumí tu consulta sin incluir datos personales ni copiar el contenido de documentos judiciales.' + navigation;
  }
  const q = normalize(input);
  if (/\b(?:venc\w* hoy|plazo (?:perentorio|judicial|vence)|in extremis|habilitacion urgente|alta urgente|caducidad|prescripcion)\b/.test(q)) {
    return 'Si hay un posible vencimiento judicial, contactá de inmediato a tu profesional o a la dependencia que interviene para confirmar cómo proceder. Para asistencia con el Portal, ' + contact + ' El chat no confirma plazos ni registra presentaciones.';
  }
  if (/[\w.+-]+@[\w.-]+\.[a-z]{2,}|\b\d{7,11}\b|\b\d{2}-\d{8}-\d\b/i.test(input) || /\b(?:mi|el|la) (?:clave|otp|pin|contrasena|password|dni|cuit|cuil|codigo) (?:es|son)\b/.test(q) || /\b(?:mi )?(?:clave|otp|pin|contrase[nñ]a|password|dni|cuit|cuil)\s*:/i.test(input)) {
    return 'Para cuidar tu información, evitá compartir contraseñas, códigos o identificadores personales por este chat. Contame qué trámite querés hacer sin incluir esos datos.' + navigation;
  }
  if (/\b(?:humano|operador|hablar con alguien|atencion personal|mi ticket|estado del ticket|abrir ticket|generar ticket)\b/.test(q)) return contact + navigation;
  if (/\b(?:me conviene|que estrategia|que recurso (?:debo|puedo)|calcul\w+.*plazo|cuando vence|asesoramiento legal|que debo alegar)\b/.test(q)) {
    return 'Puedo orientarte en el uso del Portal. Para una decisión sobre tu caso o un plazo, consultá con tu profesional o con la dependencia que interviene.' + navigation;
  }
  if (/\b(?:fuero nacional|fuero federal|lex100|scba|provincia de buenos aires|tribunal electoral|padron electoral)\b/.test(q)) {
    return 'Este chat orienta sobre el Portal del Litigante del Poder Judicial de la Ciudad de Buenos Aires. Para esa consulta, usá el canal del organismo que interviene.' + navigation;
  }
  if (!q || /^(?:0|hola|hola buen dia|buen dia|buenas|buenas tardes|buenas noches|menu|menu principal|inicio|volver|atras|ayuda)$/.test(q)) {
    return mainMenu;
  }
  if (/^(?:gracias|muchas gracias|listo gracias|salir|finalizar|terminar|chau|hasta luego)$/.test(q)) {
    return 'Gracias por consultar. Si necesitás más ayuda, escribí **menú**.';
  }
  if (/^(?:contacto|atencion humana|quiero hablar con una persona)$/.test(q)) {
    return contact + navigation;
  }
  const option = q.match(/^(?:opcion )?([0-9])(?: ([0-9]{1,2}))?$/);
  if (option) {
    const area = Number(option[1]);
    const position = Number(option[2] || 0);
    if (!topics[area - 1]) return 'Elegí una opción del 1 al 6.\n\n' + mainMenu;
    if (!option[2]) return catalog(area);
    const title = topics[area - 1][position - 1];
    if (!title) return 'Ese código no figura en este menú.\n\n' + catalog(area);
    return chooseTopic(area + '.' + position);
  }
  const named = areas.findIndex(([, name]) => normalize(name) === q);
  if (named >= 0) return catalog(named + 1);
  const trained = Object.entries(trainingPhrases).find(([, phrases]) => phrases.some(phrase => normalize(phrase) === q));
  if (trained) return chooseTopic(trained[0]);
  if (/^(?:una )?(?:causa|expediente|necesito ayuda con (?:una |mi )?(?:causa|expediente))$/.test(q)) {
    return '¿Querés iniciar una causa nueva o buscar una que ya existe?\n\n3.1 · Iniciar una causa\n5.1 · Buscar una causa\n0 · Menú principal';
  }
  if (/^(?:ayuda con )?(?:la )?firma(?: digital)?$/.test(q)) return catalog(2);
  return 'Consulta documental: Texto: ' + input.trim();
}

return route($flow.input);

const normalize = (value) => String(value ?? '').normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

const sourceLabels = new Map([
  ['https://eje.juscaba.gob.ar/iol-ui/p/inicio', 'Portal del Litigante'],
  ['https://eje.juscaba.gob.ar/iol-ui/', 'Consulta Pública de EJE'],
  ['https://firmar.gob.ar/firmador/', 'Firma Digital Remota'],
  ['https://consejo.jusbaires.gob.ar/institucional/organigrama/oficina-de-defensa-del-litigante/', 'Oficina de Defensa del Litigante']
]);
const navigation = '\n\n0 · Menú principal';
const areasByCode = ['REG', 'FD', 'ESC', 'CED', 'CON', 'SOP'];

const help = 'Podés comunicarte con la [Oficina de Defensa del Litigante](https://consejo.jusbaires.gob.ar/institucional/organigrama/oficina-de-defensa-del-litigante/) al (011) 4008-0216 / 0272 o a odl@jusbaires.gob.ar.';
const fallback = '¿En qué pantalla del Portal estás y qué querés hacer? Por ejemplo, «Mis Causas: no veo el expediente».\n\n' + help + navigation;
const unavailable = 'En este momento no pude consultar las guías del Portal. Podés volver a intentar o pedir ayuda.\n\n' + help + navigation;
const stopwords = new Set('a al algo ante como con cual cuando de del donde el en es hice la las le lo los me mi mis no o para por puedo que se si sin su sus tengo tu un una y ya'.split(' '));
const tokens = (value) => [...new Set(normalize(value).split(' ').filter(word => word.length > 2 && !stopwords.has(word)).map(word => word.replace(/(?:es|s)$/, '')))];
const steps = (answer) => {
  const sentences = answer.split(/(?<=\.)\s+(?=[A-ZÁÉÍÓÚ])/);
  if (sentences.length < 2 || sentences.length > 3 || !sentences.every(sentence => /^(?:Abrí|Accedé|Buscá|Completá|Confirmá|Conectá|Consultá|Entrá|Ingresá|Revisá|Seguí|Seleccioná|Usá|Verificá|Volvé)(?=\s|$)/.test(sentence))) return answer;
  return sentences.map((sentence, i) => (i + 1) + '. ' + sentence).join('\n');
};

function respond(question, retrieved, resolved) {
  let documents;
  try {
    documents = Array.isArray(retrieved) ? retrieved : JSON.parse(retrieved);
  } catch {
    return unavailable;
  }
  if (!Array.isArray(documents) || !documents.length) return unavailable;
  const query = normalize(question);
  const queryWords = ' ' + query + ' ';
  const selectedId = String(resolved ?? '').match(/^Consulta documental: \[([^\]]+)\]/)?.[1];
  const queryTokens = tokens(query);
  const matches = [];
  for (const document of documents) {
    const ficha = String(document?.pageContent ?? '').match(
      /^# ([^\n]+)\s+Ficha (VEC-PL-[A-Z]+-\d+)\s+Consultas relacionadas: ([^\n]+)\s+Respuesta:\s+([\s\S]+?)\s+Fuente oficial: (https:\/\/[^\s]+)\s*$/
    );
    if (!ficha) continue;
    const [, title, id, triggers, answer, source] = ficha;
    if (!sourceLabels.has(source) || (selectedId && selectedId !== id)) continue;
    const phrases = [title, ...triggers.split(',')].map(normalize).filter(Boolean);
    const phraseScore = Math.max(0, ...phrases.filter(phrase => queryWords.includes(' ' + phrase + ' ')).map(phrase => phrase.split(' ').length));
    const known = new Set(tokens(title + ' ' + triggers));
    const hits = queryTokens.filter(token => known.has(token)).length;
    const coverage = queryTokens.length ? hits / queryTokens.length : 0;
    const score = selectedId || normalize(title) === query ? 100 : phraseScore ? 10 + phraseScore : hits >= 2 && coverage >= 0.6 ? coverage : 0;
    if (score > 0) matches.push({title, id, answer, source, score});
  }
  matches.sort((a, b) => b.score - a.score);
  const [first, second] = matches;
  if (!first) return selectedId ? unavailable : fallback;
  if (second && first.id !== second.id && first.score - second.score < 0.15) {
    return '¿Te referís a **' + first.title + '** o a **' + second.title + '**?' + navigation;
  }
  const area = areasByCode.indexOf(first.id.split('-')[2]);
  const back = area >= 0 ? (area + 1) + ' · Volver  |  0 · Menú  |  Contacto' : '0 · Menú principal';
  return '**' + first.title + '**\n\n' + steps(first.answer) + '\n\n[' + sourceLabels.get(first.source) + '](' + first.source + ')\n\n' + back;
}

return respond($flow.input, $retrieved, $resolved);
